    "evidence_and_grounding": {
      "score": 5,
      "rationale": "Every pillar distinguishes supplied fixture facts (POC owners/phases, exact VM counts/OCPU, success criteria) from evidence gaps and assumptions; no fabricated observations."
    },
    "remediation_actionability": {
      "score": 5,
      "rationale": "Each finding includes concrete owner-oriented actions (e.g., 'Week 1 POC', 'Phase 2 build'), validation evidence (load test, OCI Advisor reports), and practical next steps tied to the 6-week engagement."
    }
  }
}

