artifacts.content:
{"files": {"main_tf": "terraform {
  required_version = ">= 1.0.0"
  required_providers {
    oci = {
      source  = "oracle/oci"
      version = ">= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

provider "oci" {
  tenancy_ocid = var.tenancy_ocid
  region       = var.region
}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.tenancy_ocid
}

data "oci_core_images" "ol8_image" {
  compartment_id               = var.compartment_id
  operating_system             = "Oracle Linux"
  operating_system_version     = "8.0"
  shape                        = "VM.Standard.E5.Flex"
  image_location               = "canonical-registry"
  state                        = "AVAILABLE"
  sort_by                      = "TIMECREATED"
  sort_order                   = "DESC"
}

data "oci_core_services" "core_services" {
  availability_locations {
    availability_domain = ""
  }
}

data "oci_database_db_versions" "supported_versions" {
  compartment_id        = var.compartment_id
  supports_create_db    = true
  is_rac_supported      = true
  db_system_shape       = "VM.Standard.E5.Flex"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

locals {
  suffix        = random_id.suffix.hex
  tags = {
    "customer"     = "northwind-health"
    "environment"  = "poc"
    "poc-id"       = local.suffix
  }
}

# VCN
resource "oci_core_vcn" "vcn" {
  compartment_id = var.compartment_id
  cidr_block     = "10.0.0.0/16"
  display_name   = "northwind-vcn"
  dns_label      = "northwindvcn"
  freeform_tags  = local.tags
}

# Internet Gateway
resource "oci_core_internet_gateway" "igw" {
  compartment_id = var.compartment_id
  display_name   = "northwind-igw"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

# NAT Gateway
resource "oci_core_nat_gateway" "nat_gw" {
  compartment_id = var.compartment_id
  display_name   = "northwind-nat"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

# Service Gateway
resource "oci_core_service_gateway" "svc_gw" {
  compartment_id = var.compartment_id
  display_name   = "northwind-svcgw"
  services       = [data.oci_core_services.core_services.services.0.id]
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

# Public Route Table
resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "northwind-public-rt"
  route_rules {
    network_entity_id = oci_core_internet_gateway.igw.id
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
  }
  freeform_tags = local.tags
}

# Private Route Table
resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "northwind-private-rt"
  route_rules {
    network_entity_id = oci_core_nat_gateway.nat_gw.id
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
  }
  route_rules {
    network_entity_id = oci_core_service_gateway.svc_gw.id
    destination       = data.oci_core_services.core_services.services.0.cidr_block
    destination_type  = "SERVICE_CIDR_BLOCK"
  }
  freeform_tags = local.tags
}

# Subnets
resource "oci_core_subnet" "public_lb_subnet" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  availability_domain   = null  # Regional
  cidr_block            = "10.0.0.0/24"
  display_name          = "northwind-public-lb"
  dns_label             = "publiclb"
  route_table_id        = oci_core_route_table.public_rt.id
  prohibit_public_ip_on_vnic = false
  freeform_tags         = local.tags
}

resource "oci_core_subnet" "private_web_subnet" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  availability_domain   = null
  cidr_block            = "10.0.1.0/24"
  display_name          = "northwind-private-web"
  dns_label             = "privateweb"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags         = local.tags
}

resource "oci_core_subnet" "private_app_subnet" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  availability_domain   = null
  cidr_block            = "10.0.2.0/24"
  display_name          = "northwind-private-app"
  dns_label             = "privateapp"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags         = local.tags
}

resource "oci_core_subnet" "private_db_subnet" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  availability_domain   = null
  cidr_block            = "10.0.3.0/24"
  display_name          = "northwind-private-db"
  dns_label             = "privatedb"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags         = local.tags
}

# Network Security Groups
resource "oci_core_network_security_group" "lb_nsg" {
  compartment_id = var.compartment_id
  display_name   = "northwind-lb-nsg"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

resource "oci_core_network_security_group" "web_nsg" {
  compartment_id = var.compartment_id
  display_name   = "northwind-web-nsg"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

resource "oci_core_network_security_group" "app_nsg" {
  compartment_id = var.compartment_id
  display_name   = "northwind-app-nsg"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

resource "oci_core_network_security_group" "db_nsg" {
  compartment_id = var.compartment_id
  display_name   = "northwind-db-nsg"
  vcn_id         = oci_core_vcn.vcn.id
  freeform_tags  = local.tags
}

# NSG Rules
resource "oci_core_network_security_group_security_rule" "lb_ingress_http" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "CIDR_BLOCK"
  source                    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_web" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction                 = "EGRESS"
  protocol                  = "6"
  destination_type          = "NETWORK_SECURITY_GROUP"
  destination               = oci_core_network_security_group.web_nsg.id
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_all" {
  network_security_group_id = oci_core_network_security_group.lb_nsg.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination_type          = "CIDR_BLOCK"
  destination               = "0.0.0.0/0"
}

resource "oci_core_network_security_group_security_rule" "web_ingress_lb" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.lb_nsg.id
  tcp_options {
    destination_port_range {
      max = 80
      min = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_ingress_ssh" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "CIDR_BLOCK"
  source                    = var.admin_cidr
  tcp_options {
    destination_port_range {
      max = 22
      min = 22
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_app" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction                 = "EGRESS"
  protocol                  = "6"
  destination_type          = "NETWORK_SECURITY_GROUP"
  destination               = oci_core_network_security_group.app_nsg.id
  tcp_options {
    destination_port_range {
      max = 8080
      min = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_all" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination_type          = "CIDR_BLOCK"
  destination               = "0.0.0.0/0"
}

resource "oci_core_network_security_group_security_rule" "app_ingress_web" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.web_nsg.id
  tcp_options {
    destination_port_range {
      max = 8080
      min = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_ingress_ssh" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "CIDR_BLOCK"
  source                    = var.admin_cidr
  tcp_options {
    destination_port_range {
      max = 22
      min = 22
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_db" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction                 = "EGRESS"
  protocol                  = "6"
  destination_type          = "NETWORK_SECURITY_GROUP"
  destination               = oci_core_network_security_group.db_nsg.id
  tcp_options {
    destination_port_range {
      max = 1521
      min = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_all" {
  network_security_group_id = oci_core_network_security_group.app_nsg.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination_type          = "CIDR_BLOCK"
  destination               = "0.0.0.0/0"
}

resource "oci_core_network_security_group_security_rule" "db_ingress_app" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.app_nsg.id
  tcp_options {
    destination_port_range {
      max = 1521
      min = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "db_ingress_ssh" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "CIDR_BLOCK"
  source                    = var.admin_cidr
  tcp_options {
    destination_port_range {
      max = 22
      min = 22
    }
  }
}

resource "oci_core_network_security_group_security_rule" "db_egress_all" {
  network_security_group_id = oci_core_network_security_group.db_nsg.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination_type          = "CIDR_BLOCK"
  destination               = "0.0.0.0/0"
}

# Vault
resource "oci_kms_vault" "vault" {
  compartment_id = var.compartment_id
  vault_type     = "VIRTUAL"
  display_name   = "northwind-vault"
  freeform_tags  = local.tags
}

resource "oci_kms_key" "master_key" {
  compartment_id      = var.compartment_id
  display_name        = "northwind-master-key"
  key_shape {
    algorithm = "AES"
    length    = 32
  }
  management_endpoint = oci_kms_vault.vault.vault_endpoint
  freeform_tags       = local.tags
}

# Object Storage
resource "oci_objectstorage_bucket" "claims_bucket" {
  compartment_id = var.compartment_id
  name           = "northwind-health-claims-${random_id.bucket_suffix.hex}"
  access_type    = "ObjectReadWithoutList"
  namespace      = var.namespace
  storage_tier   = "Standard"
  freeform_tags  = local.tags
}

resource "oci_objectstorage_bucket" "backup_bucket" {
  compartment_id = var.compartment_id
  name           = "northwind-health-backup-${random_id.bucket_suffix.hex}"
  access_type    = "NoPublicAccess"
  namespace      = var.namespace
  storage_tier   = "Standard"
  freeform_tags  = local.tags
}

# Logging
resource "oci_logging_log_group" "log_group" {
  compartment_id = var.compartment_id
  display_name   = "northwind-logs"
  freeform_tags  = local.tags
}

# IAM Dynamic Group and Policy
resource "oci_identity_dynamic_group" "infra_dg" {
  compartment_id = var.compartment_id
  name           = "northwind-infra-dg"
  matching_policy  = "ALL {resource.type = 'oci_core_instance', resource.compartment.id = '${var.compartment_id}', tag.customer = 'northwind-health'}"
}

resource "oci_identity_policy" "infra_policy" {
  compartment_id = var.compartment_id
  name           = "northwind-infra-policy-${local.suffix}"
  description    = "Policies for Northwind POC infrastructure"
  statements = [
    "allow dynamic-group northwind-infra-dg to read instances in compartment id '${var.compartment_id}'",
    "allow dynamic-group northwind-infra-dg to manage volume-family in compartment id '${var.compartment_id}'",
    "allow dynamic-group northwind-infra-dg to manage object-family in compartment id '${var.compartment_id}'",
    "allow dynamic-group northwind-infra-dg to use kms-family in compartment id '${var.compartment_id}'",
    "allow service database-service to manage object-family in compartment id '${var.compartment_id}'",
    "allow service database-service to read database-family in compartment id '${var.compartment_id}'",
    "allow service cloudguard-service to read log-content in tenancy"
  ]
}

# WAF
resource "oci_waf_waf_policy" "waf_policy" {
  compartment_id = var.compartment_id
  display_name   = "northwind-waf-policy"
  freeform_tags  = local.tags
}

# Flexible Load Balancer
resource "oci_load_balancer_load_balancer" "public_lb" {
  compartment_id = var.compartment_id
  display_name   = "northwind-lb"
  shape          = "flexible"
  subnet_ids     = [oci_core_subnet.public_lb_subnet.id]
  is_private     = false
  shape_details {
    minimum_bandwidth_in_gbps = "10"
    maximum_bandwidth_in_gbps = "100"
  }
  freeform_tags = local.tags
}

# LB Listener and Backend Set
resource "oci_load_balancer_backend_set" "web_backend" {
  load_balancer_id = oci_load_balancer_load_balancer.public_lb.id
  name             = "web_backend"
  policy           = "ROUND_ROBIN"
  health_checker {
    interval_in_millis = "10000"
    port               = "80"
    protocol           = "HTTP"
    url_path           = "/health"
    return_code        = "200-399"
    timeout_in_millis  = "3000"
    retries            = 3
  }
  backends {
    ip_address = oci_core_instance.web1.private_ip
    port       = "80"
    weight     = 1
  }
  backends {
    ip_address = oci_core_instance.web2.private_ip
    port       = "80"
    weight     = 1
  }
}

resource "oci_load_balancer_listener" "http_listener" {
  load_balancer_id         = oci_load_balancer_load_balancer.public_lb.id
  name                     = "http_listener"
  default_backend_set_name = oci_load_balancer_backend_set.web_backend.name
  protocol                 = "HTTP"
  port                     = "80"
}

# WAF Association (depends on LB)
resource "oci_waf_waf_policy_association" "waf_assoc" {
  waf_policy_id   = oci_waf_waf_policy.waf_policy.id
  load_balancer_id = oci_load_balancer_load_balancer.public_lb.id
}

# Web Tier Instances
resource "oci_core_instance" "web1" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-web1"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    ocpus         = 2
    memory_in_gbs = 16
  }
  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8_image.images[0].id
  }
  create_vnic_details {
    subnet_id        = oci_core_subnet.private_web_subnet.id
    display_name     = "web1-vnic"
    nsg_ids          = [oci_core_network_security_group.web_nsg.id]
    assign_public_ip = false
  }
  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }
  freeform_tags  = merge(local.tags, { "tier" = "web" })
}

resource "oci_core_instance" "web2" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[1].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-web2"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    ocpus         = 2
    memory_in_gbs = 16
  }
  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8_image.images[0].id
  }
  create_vnic_details {
    subnet_id        = oci_core_subnet.private_web_subnet.id
    display_name     = "web2-vnic"
    nsg_ids          = [oci_core_network_security_group.web_nsg.id]
    assign_public_ip = false
  }
  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }
  freeform_tags  = merge(local.tags, { "tier" = "web" })
}

# App Tier Block Volumes
resource "oci_core_volume" "app1_volume" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-app1-volume"
  size_in_gbs         = 250
  vpus_per_gb         = 20
  kms_key_id          = oci_kms_key.master_key.id
  freeform_tags       = merge(local.tags, { "tier" = "app" })
}

resource "oci_core_volume_attachment" "app1_volume_attach" {
  type       = "iscsi"
  instance_id = oci_core_instance.app1.id
  volume_id  = oci_core_volume.app1_volume.id
}

resource "oci_core_volume" "app2_volume" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[1].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-app2-volume"
  size_in_gbs         = 250
  vpus_per_gb         = 20
  kms_key_id          = oci_kms_key.master_key.id
  freeform_tags       = merge(local.tags, { "tier" = "app" })
}

resource "oci_core_volume_attachment" "app2_volume_attach" {
  type       = "iscsi"
  instance_id = oci_core_instance.app2.id
  volume_id  = oci_core_volume.app2_volume.id
}

# App Tier Instances
resource "oci_core_instance" "app1" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-app1"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    ocpus         = 4
    memory_in_gbs = 32
  }
  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8_image.images[0].id
  }
  create_vnic_details {
    subnet_id        = oci_core_subnet.private_app_subnet.id
    display_name     = "app1-vnic"
    nsg_ids          = [oci_core_network_security_group.app_nsg.id]
    assign_public_ip = false
  }
  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }
  freeform_tags  = merge(local.tags, { "tier" = "app" })
}

resource "oci_core_instance" "app2" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[1].name
  compartment_id      = var.compartment_id
  display_name        = "northwind-app2"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    ocpus         = 4
    memory_in_gbs = 32
  }
  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.ol8_image.images[0].id
  }
  create_vnic_details {
    subnet_id        = oci_core_subnet.private_app_subnet.id
    display_name     = "app2-vnic"
    nsg_ids          = [oci_core_network_security_group.app_nsg.id]
    assign_public_ip = false
  }
  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }
  freeform_tags  = merge(local.tags, { "tier" = "app" })
}

# Database
resource "oci_database_db_system" "northwind_db" {
  compartment_id   = var.compartment_id
  subnet_id        = oci_core_subnet.private_db_subnet.id
  shape            = "VM.Standard.E5.Flex"
  node_count       = 2
  cluster_name     = "northwind-cluster"
  hostname_label   = "northwinddb"
  data_storage_percentage = 40
  admin_password   = var.db_admin_password
  db_name          = "NWPDB"
  db_workload      = "OLTP"
  database_edition = "ENTERPRISE_EDITION"
  db_version       = data.oci_database_db_versions.supported_versions.db_versions[0].version
  nsg_ids          = [oci_core_network_security_group.db_nsg.id]
