    ocpus            = 2
    memory_size_in_gbs = 64
  }
  backup_destination {
    type      = "OBJECT_STORE"
    bucket_name = oci_objectstorage_bucket.backup_bucket.name
    nsg_ids   = [oci_core_network_security_group.db_nsg.id]
  }
  ssh_public_keys = [var.ssh_public_key]
  freeform_tags   = merge(local.tags, { "tier" = "db" })
