{"files": {"main_tf": "locals {
  label_prefix = var.label_prefix != "" ? var.label_prefix : "nwhealth-"
}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.compartment_id
}

data "oci_core_images" "instance_image" {
  compartment_id           = var.compartment_id
  operating_system         = "Oracle Linux"
  operating_system_version = "8"
  shape                    = "VM.Standard.E5.Flex"
  state                    = "AVAILABLE"
  sort_by                  = "TIMECREATED"
  sort_order               = "DESC"
}

data "oci_core_services" "core_services" {
  compartment_id = var.compartment_id
}

data "oci_objectstorage_namespace" "namespace" {}

data "oci_identity_dynamic_groups" "test" {
  compartment_id = var.compartment_id
}

# VCN
resource "oci_core_vcn" "vcn" {
  cidr_block     = "10.0.0.0/16"
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}vcn"
  dns_label      = "northwind"
}

# Internet Gateway
resource "oci_core_internet_gateway" "igw" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}igw"
  vcn_id         = oci_core_vcn.vcn.id
}

# NAT Gateway
resource "oci_core_nat_gateway" "natgw" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}natgw"
  vcn_id         = oci_core_vcn.vcn.id
}

# Service Gateway
resource "oci_core_service_gateway" "service_gateway" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}servicegw"
  services {
    service_id = data.oci_core_services.core_services.services[0].id
  }
  vcn_id = oci_core_vcn.vcn.id
}

# Route Tables
resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}public-rt"
  route_rules {
    description       = "Internet Gateway"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_internet_gateway.igw.id
  }
}

resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}private-rt"
  route_rules {
    description       = "NAT Gateway"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_nat_gateway.natgw.id
  }
  route_rules {
    description       = "OCI Services"
    destination       = "all-ams-services-in-oracle-services-network"
    destination_type  = "SERVICE_CIDR_BLOCK"
    network_entity_id = oci_core_service_gateway.service_gateway.id
  }
}

# Subnets
resource "oci_core_subnet" "public_subnet" {
  vcn_id                      = oci_core_vcn.vcn.id
  compartment_id              = var.compartment_id
  cidr_block                  = "10.0.0.0/24"
  display_name                = "${local.label_prefix}public-subnet"
  dns_label                   = "public"
  route_table_id              = oci_core_route_table.public_rt.id
  prohibit_public_ip_on_vnic  = false
}

resource "oci_core_subnet" "web_subnet" {
  vcn_id                      = oci_core_vcn.vcn.id
  compartment_id              = var.compartment_id
  cidr_block                  = "10.0.1.0/24"
  display_name                = "${local.label_prefix}web-subnet"
  dns_label                   = "web"
  route_table_id              = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic  = true
}

resource "oci_core_subnet" "app_subnet" {
  vcn_id                      = oci_core_vcn.vcn.id
  compartment_id              = var.compartment_id
  cidr_block                  = "10.0.2.0/24"
  display_name                = "${local.label_prefix}app-subnet"
  dns_label                   = "app"
  route_table_id              = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic  = true
}

resource "oci_core_subnet" "db_subnet" {
  vcn_id                      = oci_core_vcn.vcn.id
  compartment_id              = var.compartment_id
  cidr_block                  = "10.0.3.0/24"
  display_name                = "${local.label_prefix}db-subnet"
  dns_label                   = "db"
  route_table_id              = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic  = true
}

# NSGs
resource "oci_core_network_security_group" "nsg_lb" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}nsg-lb"
}

resource "oci_core_network_security_group" "nsg_web" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}nsg-web"
}

resource "oci_core_network_security_group" "nsg_app" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}nsg-app"
}

resource "oci_core_network_security_group" "nsg_db" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${local.label_prefix}nsg-db"
}

# NSG Rules
# LB NSG
resource "oci_core_network_security_group_security_rule" "lb_ingress_https" {
  network_security_group_id = oci_core_network_security_group.nsg_lb.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source                    = "0.0.0.0/0"
  tcp_options {
    destination_port_range {
      min = 443
      max = 443
    }
  }
}

resource "oci_core_network_security_group_security_rule" "lb_egress_web" {
  network_security_group_id     = oci_core_network_security_group.nsg_lb.id
  direction                     = "EGRESS"
  protocol                      = "6"
  destination_type              = "NETWORK_SECURITY_GROUP"
  destination                   = oci_core_network_security_group.nsg_web.id
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

# Web NSG
resource "oci_core_network_security_group_security_rule" "web_ingress_lb" {
  network_security_group_id = oci_core_network_security_group.nsg_web.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.nsg_lb.id
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_app" {
  network_security_group_id     = oci_core_network_security_group.nsg_web.id
  direction                     = "EGRESS"
  protocol                      = "6"
  destination_type              = "NETWORK_SECURITY_GROUP"
  destination                   = oci_core_network_security_group.nsg_app.id
  tcp_options {
    destination_port_range {
      min = 8080
      max = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_egress_internet" {
  network_security_group_id = oci_core_network_security_group.nsg_web.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination               = "0.0.0.0/0"
}

# App NSG
resource "oci_core_network_security_group_security_rule" "app_ingress_web" {
  network_security_group_id = oci_core_network_security_group.nsg_app.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.nsg_web.id
  tcp_options {
    destination_port_range {
      min = 8080
      max = 8080
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_db" {
  network_security_group_id     = oci_core_network_security_group.nsg_app.id
  direction                     = "EGRESS"
  protocol                      = "6"
  destination_type              = "NETWORK_SECURITY_GROUP"
  destination                   = oci_core_network_security_group.nsg_db.id
  tcp_options {
    destination_port_range {
      min = 1521
      max = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "app_egress_internet" {
  network_security_group_id = oci_core_network_security_group.nsg_app.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination               = "0.0.0.0/0"
}

# DB NSG
resource "oci_core_network_security_group_security_rule" "db_ingress_app" {
  network_security_group_id = oci_core_network_security_group.nsg_db.id
  direction                 = "INGRESS"
  protocol                  = "6"
  source_type               = "NETWORK_SECURITY_GROUP"
  source                    = oci_core_network_security_group.nsg_app.id
  tcp_options {
    destination_port_range {
      min = 1521
      max = 1521
    }
  }
}

resource "oci_core_network_security_group_security_rule" "db_egress_internet" {
  network_security_group_id = oci_core_network_security_group.nsg_db.id
  direction                 = "EGRESS"
  protocol                  = "ALL"
  destination               = "0.0.0.0/0"
}

# Vault
resource "oci_kms_vault" "vault" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}vault"
  vault_type     = "DEFAULT"
}

resource "oci_kms_key" "encryption_key" {
  compartment_id      = oci_kms_vault.vault.id
  display_name        = "${local.label_prefix}encryption-key"
  key_shape {
    algorithm = "AES"
    length    = 32
  }
  management_endpoint = oci_kms_vault.vault.management_endpoint
}

# Object Storage
resource "oci_objectstorage_bucket" "claims_bucket" {
  compartment_id = var.compartment_id
  namespace      = data.oci_objectstorage_namespace.namespace.namespace
  name           = lower("${local.label_prefix}claims-bucket-${random_string.bucket_suffix.result}")
  access_type    = "NoPublicAccess"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "oci_limits_quota" "object_storage_quota" {
  compartment_id = var.compartment_id
  description    = "100 GB Object Storage quota for Northwind"
  name           = "${local.label_prefix}os-quota"
  quotas {
    service_name = "objectstorage"
    name         = "OBJECT_STORAGE_TOTAL_GB"
    value        = 100
  }
}

# Load Balancer
resource "oci_load_balancer_load_balancer" "flex_lb" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}flex-lb"
  is_private     = false
  shape          = "flexible"
  shape_details {
    maximum_bandwidth_in_mbps = 100
    minimum_bandwidth_in_mbps = 10
  }
  subnet_ids = [oci_core_subnet.public_subnet.id]
  network_security_group_ids = [oci_core_network_security_group.nsg_lb.id]
}

resource "oci_load_balancer_backend_set" "web_backend_set" {
  load_balancer_id         = oci_load_balancer_load_balancer.flex_lb.id
  name                     = "web-backend-set"
  policy                   = "ROUND_ROBIN"
  health_checker {
    interval_in_millis = 10000
    port               = 80
    protocol           = "HTTP"
    retries            = 3
    timeout_in_millis  = 3000
    url_path           = "/health"
  }
}

resource "oci_load_balancer_listener" "lb_listener" {
  load_balancer_id         = oci_load_balancer_load_balancer.flex_lb.id
  name                     = "http-listener"
  default_backend_set_name = oci_load_balancer_backend_set.web_backend_set.name
  protocol                 = "HTTP"
  port                     = "80"
}

# Backends will be added after instances

# WAF
resource "oci_waf_waf" "waf" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}waf"
}

resource "oci_waf_web_app_firewall_policy" "waf_policy" {
  compartment_id = oci_waf_waf.waf.id
  display_name   = "${local.label_prefix}waf-policy"
  waf_id         = oci_waf_waf.waf.id
}

# Note: Associate WAF to listener by adding waf_policy_id to listener after creation if needed

# Compute Instances
resource "oci_core_instance" "web_01" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "${local.label_prefix}web-01"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    memory_in_gbs = 16
    ocpus         = 2
  }
