resource "oci_core_instance" "app_02" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "${local.label_prefix}app-02"
  shape               = "VM.Standard.E5.Flex"
  shape_config {
    memory_in_gbs = 32
    ocpus         = 4
  }
  create_vnic_details {
    subnet_id        = oci_core_subnet.app_subnet.id
    nsg_ids          = [oci_core_network_security_group.nsg_app.id]
    private_ip       = "10.0.2.11"
    assign_public_ip = false
  }
  source_details {
    source_type = "image"
    image_id    = data.oci_core_images.instance_image.images[0].id
  }
  metadata = {
    ssh_authorized_keys = var.ssh_public_key
  }
  freeform_tags = {
    "customer" = "northwind"
    "tier"     = "app"
  }
  defined_tags = {
    "Oracle-Tags.CreatedBy" = "terraform"
  }
}

# Block Volume
resource "oci_core_volume" "app_block_volume" {
  availability_domain = data.oci_identity_availability_domains.ads.availability_domains[0].name
  compartment_id      = var.compartment_id
  display_name        = "${local.label_prefix}app-blockvol"
  size_in_gbs         = 500
  kms_key_id          = oci_kms_key.encryption_key.id
  vpus_per_gb         = 20
}

resource "oci_core_volume_attachment" "app_block_attach" {
  attachment_type = "iscsi"
  compartment_id  = var.compartment_id
  instance_id     = oci_core_instance.app_01.id
  volume_id       = oci_core_volume.app_block_volume.id
}

# Load Balancer Backends
resource "oci_load_balancer_backend" "web_backend_01" {
  backendset_name = oci_load_balancer_backend_set.web_backend_set.name
  ip_address      = oci_core_instance.web_01.private_ip
  load_balancer_id = oci_load_balancer_load_balancer.flex_lb.id
  port            = 80
}

resource "oci_load_balancer_backend" "web_backend_02" {
  backendset_name = oci_load_balancer_backend_set.web_backend_set.name
  ip_address      = oci_core_instance.web_02.private_ip
  load_balancer_id = oci_load_balancer_load_balancer.flex_lb.id
  port            = 80
}

# Database (Autonomous for HA simplicity, matches sizing)
resource "oci_database_autonomous_database" "claims_db" {
  compartment_id        = var.compartment_id
  cpu_core_count        = 4
  data_storage_size_in_tbs = 1
  admin_password        = var.db_admin_password
  db_name               = upper("${replace(local.label_prefix, "-", "")}db")
  display_name          = "${local.label_prefix}claims-db"
  db_workload           = "TransactionProcessing"
  is_dedicated          = false
  license_model         = "LICENSE_INCLUDED"
  nsg_ids               = [oci_core_network_security_group.nsg_db.id]
  private_endpoint {
    compartment_id = var.compartment_id
    nsg_ids        = [oci_core_network_security_group.nsg_db.id]
    subnet_id      = oci_core_subnet.db_subnet.id
  }
  freeform_tags = {
    "customer" = "northwind"
  }
}

# Logging
resource "oci_logging_log_group" "log_group" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}log-group"
}

# Monitoring - Example alarm for LB backend health
resource "oci_monitoring_alarm" "lb_health_alarm" {
  compartment_id = var.compartment_id
  display_name   = "${local.label_prefix}lb-backend-health"
  metric_compartment_id = var.compartment_id
  namespace   = "oci_load_balancer"
  query       = "BackendStateUpRatio[1m]{backendSetName = \"web-backend-set\"}.mean() < 1"
  severity    = "CRITICAL"
  destinations {
    destination_id = oci_notifications_topic.topic.id # dummy, create topic if needed
    label          = "Ops Topic"
  }
}

# IAM Dynamic Group for instances
resource "oci_identity_dynamic_group" "northwind_instances" {
  compartment_id = var.compartment_id
  name           = "${local.label_prefix}instances-dg"
  matching_rule  = "ANY {resource.type = 'instance', tag.customer.value = 'northwind', resource.compartment.id = '${var.compartment_id}'}"
}

# IAM Policies
resource "oci_identity_policy" "instances_access" {
  compartment_id = var.compartment_id
  name           = "${local.label_prefix}instances-policy"
  description    = "Allow Northwind instances access to services"
  statements = [
    "allow dynamic-group ${oci_identity_dynamic_group.northwind_instances.name} to read object-family in compartment id '${var.compartment_id}'",
    "allow dynamic-group ${oci_identity_dynamic_group.northwind_instances.name} to manage log-content in compartment id '${var.compartment_id}'",
    "allow dynamic-group ${oci_identity_dynamic_group.northwind_instances.name} to read metrics in tenancy",
    "allow dynamic-group ${oci_identity_dynamic_group.northwind_instances.name} to use kms-family in compartment id '${oci_kms_vault.vault.id}'",
    "allow dynamic-group ${oci_identity_dynamic_group.northwind_instances.name} to manage volume-family in compartment id '${var.compartment_id}'"
  ]
}

resource "oci_identity_policy" "db_access" {
  compartment_id = var.compartment_id
  name           = "${local.label_prefix}db-policy"
  description    = "Allow access to DB services"
  statements = [
    "allow group ${var.group_name} to manage database-family in compartment id '${var.compartment_id}'",
    "allow service database to read object-family in compartment id '${var.compartment_id}'"
  ]
