artifacts.content:
{"files": {"main_tf": "terraform {
  required_providers {
    oci = {
      source  = "oracle/oci"
      version = "~> 5.33.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6.0"
    }
  }
}

provider "oci" {
  region = var.region
}

provider "random" {}

data "oci_identity_tenancy" "tenancy" {
  tenancy_id = var.tenancy_ocid
}

data "oci_identity_availability_domains" "ads" {
  compartment_id = var.compartment_id
}

data "oci_core_images" "ol8" {
  compartment_id = var.compartment_id
  operating_system        = "Oracle Linux"
  operating_system_version = "8"
  shape                   = "VM.Standard.E5.Flex"
  sort_by                 = "TIMECREATED"
  sort_order              = "DESC"
}

data "oci_core_services" "core_services" {}

data "oci_core_volume_backup_policies" "backup_policies" {
  compartment_id = var.tenancy_ocid
}

data "oci_database_db_versions" "db_versions" {
  compartment_id = var.compartment_id
}

locals {
  ad1 = data.oci_identity_availability_domains.ads.availability_domains[0].name
  ad2 = length(data.oci_identity_availability_domains.ads.availability_domains) > 1 ? data.oci_identity_availability_domains.ads.availability_domains[1].name : data.oci_identity_availability_domains.ads.availability_domains[0].name
  bronze_backup_policy_id = [for p in data.oci_core_volume_backup_policies.backup_policies.volume_backup_policies : p.id if p.display_name == "Bronze"][0]
}

# VCN
resource "oci_core_vcn" "vcn" {
  compartment_id = var.compartment_id
  cidr_block     = "10.0.0.0/16"
  display_name   = var.label_prefix
  dns_label      = lower(replace(var.label_prefix, "_", "-"))
  freeform_tags = {
    "poc" = "northwind"
  }
}

resource "oci_core_internet_gateway" "ig" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-ig"
}

resource "oci_core_service_gateway" "svc_gw" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-svc-gw"
  services {
    service_id = data.oci_core_services.core_services.services[0].id
  }
}

resource "oci_core_route_table" "public_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-public-rt"
  route_rules {
    description       = "Internet Gateway"
    destination       = "0.0.0.0/0"
    destination_type  = "CIDR_BLOCK"
    network_entity_id = oci_core_internet_gateway.ig.id
  }
}

resource "oci_core_route_table" "private_rt" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-private-rt"
  route_rules {
    description       = "OCI Services"
    destination       = data.oci_core_services.core_services.services[0].cidr_block
    destination_type  = "SERVICE_CIDR_BLOCK"
    network_entity_id = oci_core_service_gateway.svc_gw.id
  }
}

# Subnets
resource "oci_core_subnet" "public" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  cidr_block            = "10.0.0.0/24"
  display_name          = "${var.label_prefix}-public"
  dns_label             = "public"
  route_table_id        = oci_core_route_table.public_rt.id
  prohibit_public_ip_on_vnic = false
  freeform_tags = {
    "poc" = "northwind"
  }
}

resource "oci_core_subnet" "private_web" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  cidr_block            = "10.0.1.0/24"
  display_name          = "${var.label_prefix}-private-web"
  dns_label             = "pweb"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags = {
    "poc" = "northwind"
  }
}

resource "oci_core_subnet" "private_app" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  cidr_block            = "10.0.2.0/24"
  display_name          = "${var.label_prefix}-private-app"
  dns_label             = "papp"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags = {
    "poc" = "northwind"
  }
}

resource "oci_core_subnet" "private_db" {
  compartment_id        = var.compartment_id
  vcn_id                = oci_core_vcn.vcn.id
  cidr_block            = "10.0.3.0/24"
  display_name          = "${var.label_prefix}-private-db"
  dns_label             = "pdb"
  route_table_id        = oci_core_route_table.private_rt.id
  prohibit_public_ip_on_vnic = true
  freeform_tags = {
    "poc" = "northwind"
  }
}

# NSGs
resource "oci_core_network_security_group" "web_nsg" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-web-nsg"
}

resource "oci_core_network_security_group" "app_nsg" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-app-nsg"
}

resource "oci_core_network_security_group" "db_nsg" {
  compartment_id = var.compartment_id
  vcn_id         = oci_core_vcn.vcn.id
  display_name   = "${var.label_prefix}-db-nsg"
}

# Web NSG Rules
resource "oci_core_network_security_group_security_rule" "web_ingress_80" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction = "INGRESS"
  protocol = "6"
  source = oci_core_subnet.public.cidr_block
  source_type = "CIDR_BLOCK"
  tcp_options {
    destination_port_range {
      min = 80
      max = 80
    }
  }
}

resource "oci_core_network_security_group_security_rule" "web_ingress_443" {
  network_security_group_id = oci_core_network_security_group.web_nsg.id
  direction = "INGRESS"
  protocol = "6"
  source = oci_core_subnet.public.cidr_block
